FILES={'lifecycle.py': '"""Pure owned-guest admission and lifecycle rules. No host operations on import.\n\nObservations are supplied by a separately qualified, authenticated host adapter.\nThis module never treats a guest-provided dictionary as an authenticated receipt.\nNative activation requires that adapter; this source alone cannot launch a VM.\n"""\nfrom dataclasses import dataclass, replace\nfrom enum import Enum\nfrom hashlib import sha256\nfrom typing import Mapping\nimport json\nimport math\n\nGIB = 1 << 30\nMIB = 1 << 20\nGUEST = 19 * GIB\nSUPPORT = GIB\nRPC_TOTAL = GUEST + SUPPORT\nPENDING = 39388 * MIB\nHOST_FLOOR = 18 * GIB\nVARIATION = GIB\nDISK_FLOOR = 16 * GIB\nBOOT_CAP = 4 * GIB\nARTIFACT_CAP = 256 * MIB\nSTARTUP_MS = 900000\n\n\nclass Refusal(ValueError):\n    pass\n\n\ndef require(condition, reason):\n    if not condition:\n        raise Refusal(reason)\n\n\ndef uint(value, name):\n    require(type(value) is int and value >= 0, \'invalid \' + name)\n    return value\n\n\ndef digest(value):\n    require(type(value) is str and len(value) == 64\n            and all(c in \'0123456789abcdef\' for c in value), \'invalid digest\')\n    return value\n\n\ndef canonical_hash(value):\n    return sha256(json.dumps(value, sort_keys=True, separators=(\',\', \':\'),\n                             allow_nan=False).encode()).hexdigest()\n\n\n@dataclass(frozen=True)\nclass Identity:\n    host_boot: str\n    attempt: str\n    vm_guid: str\n    manifest_sha256: str\n\n    def validate(self):\n        for value in (self.host_boot, self.attempt, self.vm_guid):\n            require(type(value) is str and 1 <= len(value) <= 128\n                    and all(c.isalnum() or c in \'-_\' for c in value), \'invalid identity\')\n        digest(self.manifest_sha256)\n\n\n@dataclass(frozen=True)\nclass GrowthPolicy:\n    """Operational margin, not a guarantee against arbitrary administrative writes."""\n    disk_margin_bytes: int\n    maximum_growth_bytes_per_second: int\n    sample_ms: int\n    maximum_observation_ms: int\n    shutdown_ms: int\n    force_stop_ms: int\n    qualification_sha256: str\n\n    def validate(self):\n        for name in (\'disk_margin_bytes\', \'maximum_growth_bytes_per_second\',\n                     \'sample_ms\', \'maximum_observation_ms\', \'shutdown_ms\', \'force_stop_ms\'):\n            require(uint(getattr(self, name), name) > 0, \'growth policy must be positive\')\n        require(self.sample_ms <= 1000 and self.maximum_observation_ms <= 2000,\n                \'unbounded observation gap\')\n        require(self.shutdown_ms <= 30000 and self.force_stop_ms <= 15000,\n                \'unbounded cleanup grace\')\n        window = self.sample_ms + self.maximum_observation_ms + self.shutdown_ms + self.force_stop_ms\n        needed = math.ceil(self.maximum_growth_bytes_per_second * window / 1000)\n        require(self.disk_margin_bytes >= needed, \'disk margin cannot cover qualified stop window\')\n        digest(self.qualification_sha256)\n\n\n@dataclass(frozen=True)\nclass Observation:\n    identity: Identity\n    monotonic_ms: int\n    physical_free_bytes: int\n    disk_free_bytes: int\n    support_charged_bytes: int\n    owned_memory_bytes: int\n    artifact_bytes: int\n    pending_complete: bool\n    existing_vm_set_sha256: str\n    existing_process_set_sha256: str\n    pending_sha256: str\n    # Immutable initial artifact digest from the protected admission record,\n    # NOT a live content hash of the guest\'s writable VHDX.\n    admitted_boot_sha256: str\n    host_authenticated: bool\n    runtime_boot_identity_sha256: str\n    runtime_boot_allocated_bytes: int\n\n    def validate(self, expected, now_ms, maximum_age_ms):\n        self.identity.validate()\n        require(self.identity == expected, \'observation identity changed\')\n        for name in (\'monotonic_ms\', \'physical_free_bytes\', \'disk_free_bytes\',\n                     \'support_charged_bytes\', \'owned_memory_bytes\', \'artifact_bytes\',\n                     \'runtime_boot_allocated_bytes\'):\n            uint(getattr(self, name), name)\n        require(self.host_authenticated is True and self.pending_complete is True,\n                \'missing authenticated complete host observation\')\n        require(0 <= now_ms - self.monotonic_ms <= maximum_age_ms, \'stale or future observation\')\n        for value in (self.existing_vm_set_sha256, self.existing_process_set_sha256,\n                      self.pending_sha256, self.admitted_boot_sha256,\n                      self.runtime_boot_identity_sha256):\n            digest(value)\n        require(self.support_charged_bytes <= SUPPORT, \'support budget exceeded\')\n        require(self.owned_memory_bytes <= GUEST, \'guest memory budget exceeded\')\n        require(self.artifact_bytes <= ARTIFACT_CAP, \'owned artifact budget exceeded\')\n        require(self.runtime_boot_allocated_bytes <= BOOT_CAP, \'boot file allocation exceeded\')\n\n\ndef admit(observation, identity, now_ms, policy, prerequisites, expected_boot):\n    """Initial free-memory calculation includes the entire future allocation once."""\n    policy.validate()\n    uint(now_ms, \'admission clock\')\n    observation.validate(identity, now_ms, 10000)\n    require(observation.owned_memory_bytes == 0, \'initial admission already has owned allocation\')\n    require(observation.support_charged_bytes == 0, \'initial support allocation must be zero\')\n    require(observation.physical_free_bytes >= RPC_TOTAL + PENDING + HOST_FLOOR + VARIATION,\n            \'insufficient memory after full pending allowance\')\n    require(observation.disk_free_bytes >= DISK_FLOOR + BOOT_CAP + ARTIFACT_CAP\n            + policy.disk_margin_bytes, \'insufficient disk after boot and growth allowance\')\n    require(observation.admitted_boot_sha256 == digest(expected_boot), \'boot artifact changed\')\n    # Digests must be supplied by the reviewed root manifest, not guest discovery.\n    needed = {\'guest_dependencies\', \'boot_and_seed\', \'attachment_and_fencing\',\n              \'readiness_verifier\', \'guardian_adapter\', \'disk_growth_qualification\'}\n    require(type(prerequisites) is dict and set(prerequisites) == needed,\n            \'incomplete or unexpected activation closure\')\n    for value in prerequisites.values():\n        digest(value)\n    require(prerequisites[\'disk_growth_qualification\'] == policy.qualification_sha256,\n            \'growth qualification does not match\')\n    return canonical_hash({\'identity\': identity.__dict__, \'observation\': observation.__dict__ | {\n        \'identity\': identity.__dict__}, \'policy\': policy.__dict__, \'prerequisites\': prerequisites})\n\n\nclass Phase(Enum):\n    CREATED_OFF = \'created-off\'\n    ARMED = \'armed\'\n    STARTING = \'starting\'\n    READY_TRIAL = \'ready-trial\'\n    STOPPING = \'stopping\'\n    STOPPED_HELD = \'stopped-held\'\n    RELEASED = \'released\'\n    QUARANTINED = \'quarantined\'\n\n\n@dataclass(frozen=True)\nclass State:\n    identity: Identity\n    phase: Phase\n    baseline_vm_sha256: str\n    baseline_process_sha256: str\n    baseline_pending_sha256: str\n    boot_sha256: str\n    deadline_ms: int\n    last_ms: int\n    origin_ms: int\n    admission_sha256: str\n    policy_sha256: str\n    runtime_boot_identity_sha256: str\n    last_sequence: int = -1\n    reason: str = \'\'\n    cleanup_required: bool = True\n    requires_ownership_revalidation: bool = False\n\n    def validate(self, policy):\n        self.identity.validate()\n        require(isinstance(self.phase, Phase), \'invalid phase\')\n        for name in (\'origin_ms\', \'deadline_ms\', \'last_ms\'):\n            uint(getattr(self, name), name)\n        require(self.deadline_ms == self.origin_ms + STARTUP_MS,\n                \'deadline must equal original startup boundary plus 900 seconds\')\n        require(self.last_ms >= self.origin_ms, \'state clock precedes origin\')\n        require(type(self.last_sequence) is int and self.last_sequence >= -1, \'invalid sequence\')\n        require(type(self.cleanup_required) is bool, \'invalid cleanup obligation\')\n        require(type(self.requires_ownership_revalidation) is bool, \'invalid revalidation obligation\')\n        require(self.cleanup_required == (self.phase != Phase.RELEASED), \'cleanup obligation lost\')\n        require(self.phase != Phase.RELEASED or not self.requires_ownership_revalidation,\n                \'released with unresolved ownership\')\n        require(self.phase != Phase.QUARANTINED or self.requires_ownership_revalidation,\n                \'quarantine lost ownership revalidation\')\n        for value in (self.admission_sha256, self.policy_sha256, self.runtime_boot_identity_sha256,\n                      self.baseline_vm_sha256, self.baseline_process_sha256,\n                      self.baseline_pending_sha256, self.boot_sha256):\n            digest(value)\n        policy.validate()\n        require(canonical_hash(policy.__dict__) == self.policy_sha256, \'admitted policy changed\')\n\n\ndef initial_state(observation, identity, origin_ms, policy, prerequisites, expected_boot):\n    """Only successful admission creates the initial state and fixed deadline.\n\n    The adapter must persist/authenticate this entire state before native start.\n    Python objects/hash fields do not protect against a malicious local caller;\n    resumed bytes must match the protected admission record before deserialization.\n    """\n    admission = admit(observation, identity, origin_ms, policy, prerequisites, expected_boot)\n    state = State(identity, Phase.CREATED_OFF, observation.existing_vm_set_sha256,\n        observation.existing_process_set_sha256, observation.pending_sha256,\n        observation.admitted_boot_sha256, origin_ms + STARTUP_MS, origin_ms,\n        origin_ms, admission, canonical_hash(policy.__dict__), observation.runtime_boot_identity_sha256)\n    state.validate(policy)\n    return state\n\n\n@dataclass(frozen=True)\nclass Receipt:\n    identity: Identity\n    sequence: int\n    monotonic_ms: int\n    authenticated: bool\n    issuer: str\n    data: Mapping\n\n\ndef next_state(state, event, receipt, now_ms, policy):\n    """Reducer cannot perform a VM operation. Adapter must enforce returned state.\n\n    No event extends a deadline, releases a failed cleanup, or authorizes persistent\n    production handover. A ready trial still stops at its original boundary.\n    """\n    state.validate(policy)\n    uint(now_ms, \'clock\')\n    require(state.phase != Phase.RELEASED, \'terminal state\')\n    if now_ms < state.last_ms:\n        return replace(state, phase=Phase.QUARANTINED, reason=\'monotonic clock rollback\',\n                       requires_ownership_revalidation=True)\n    if receipt.identity != state.identity or receipt.authenticated is not True:\n        return replace(state, phase=Phase.QUARANTINED, reason=\'receipt authority mismatch\', last_ms=now_ms,\n                       requires_ownership_revalidation=True)\n    require(type(receipt.sequence) is int and receipt.sequence > state.last_sequence,\n            \'replayed or out-of-order receipt\')\n    uint(receipt.monotonic_ms, \'receipt clock\')\n    require(0 <= now_ms - receipt.monotonic_ms <= policy.maximum_observation_ms,\n            \'receipt stale or from future\')\n    s = replace(state, last_ms=now_ms, last_sequence=receipt.sequence)\n    if state.phase == Phase.QUARANTINED:\n        # Quarantine freezes normal progression, NEVER the independently held\n        # cleanup obligation for the original protected identity.\n        require(event in (\'fail\', \'off\') and receipt.issuer in (\'host-guardian\', \'independent-deadline\')\n                and receipt.data.get(\'original_ownership_revalidated\') is True,\n                \'quarantined cleanup requires original ownership revalidation\')\n    if now_ms >= state.deadline_ms and state.phase not in (Phase.STOPPING, Phase.STOPPED_HELD, Phase.QUARANTINED):\n        return replace(s, phase=Phase.STOPPING, reason=\'startup deadline\')\n    if event == \'arm\':\n        require(state.phase == Phase.CREATED_OFF and receipt.issuer == \'host-guardian\', \'unexpected arm\')\n        require(receipt.data.get(\'live_instance\') is True and receipt.data.get(\'independent_deadline_live\') is True\n                and receipt.data.get(\'start_fence_armed\') is True\n                and receipt.data.get(\'deadline_ms\') == state.deadline_ms, \'guardian not independently armed\')\n        return replace(s, phase=Phase.ARMED)\n    if event == \'start\':\n        require(state.phase == Phase.ARMED and receipt.issuer == \'host-controller\', \'start without guardian\')\n        require(receipt.data.get(\'owned_start_worker_bound\') is True, \'unfenced start worker\')\n        return replace(s, phase=Phase.STARTING)\n    if event == \'observe\':\n        require(state.phase in (Phase.ARMED, Phase.STARTING, Phase.READY_TRIAL)\n                and receipt.issuer == \'host-guardian\', \'unexpected resource observation\')\n        o = receipt.data.get(\'observation\')\n        require(isinstance(o, Observation), \'typed resource observation required\')\n        try:\n            o.validate(state.identity, now_ms, policy.maximum_observation_ms)\n            require(o.existing_vm_set_sha256 == state.baseline_vm_sha256\n                    and o.existing_process_set_sha256 == state.baseline_process_sha256\n                    and o.pending_sha256 == state.baseline_pending_sha256,\n                    \'unreviewed workload change\')\n            require(o.admitted_boot_sha256 == state.boot_sha256, \'boot admission changed\')\n            require(o.runtime_boot_identity_sha256 == state.runtime_boot_identity_sha256,\n                    \'runtime boot file identity changed\')\n            # OS free already reflects resident RPC memory. Reserve only remaining\n            # guest/support capacity; keep the full conservative prospective allowance.\n            remaining = GUEST - o.owned_memory_bytes + SUPPORT - o.support_charged_bytes\n            require(o.physical_free_bytes >= remaining + PENDING + HOST_FLOOR + VARIATION,\n                    \'running host headroom insufficient\')\n            require(o.disk_free_bytes >= DISK_FLOOR + policy.disk_margin_bytes,\n                    \'disk growth guard\')\n        except Refusal as error:\n            return replace(s, phase=Phase.STOPPING, reason=str(error))\n        return s\n    if event == \'ready\':\n        require(state.phase == Phase.STARTING and receipt.issuer == \'qualified-readiness-verifier\',\n                \'unexpected readiness authority\')\n        require(receipt.data.get(\'verified_chain_set\') == (\'l1-execution\', \'l1-consensus\', \'base-execution\', \'base-rollup\')\n                and receipt.data.get(\'guardian_live\') is True and receipt.data.get(\'resource_receipt_current\') is True\n                and receipt.data.get(\'attachment_fenced\') is True, \'incomplete whole-stack readiness\')\n        return replace(s, phase=Phase.READY_TRIAL)\n    if event == \'fail\':\n        require(receipt.issuer in (\'host-controller\', \'host-guardian\', \'independent-deadline\'), \'wrong failure issuer\')\n        return replace(s, phase=Phase.STOPPING, reason=\'bounded trial failure\')\n    if event == \'off\':\n        require(state.phase in (Phase.STOPPING, Phase.QUARANTINED)\n                and receipt.issuer == \'host-guardian\', \'unexpected off receipt\')\n        require(not state.requires_ownership_revalidation\n                or receipt.data.get(\'original_ownership_revalidated\') is True,\n                \'original ownership revalidation remains required\')\n        require(receipt.data.get(\'vm_state\') == \'Off\' and receipt.data.get(\'assigned_memory_bytes\') == 0\n                and receipt.data.get(\'start_worker_dead\') is True and receipt.data.get(\'late_start_fenced\') is True,\n                \'owned VM stop not proven\')\n        return replace(s, phase=Phase.STOPPED_HELD, requires_ownership_revalidation=False)\n    if event == \'release\':\n        require(state.phase == Phase.STOPPED_HELD and receipt.issuer == \'host-controller\', \'unexpected release\')\n        require(receipt.data.get(\'guest_write_fence_confirmed\') is True\n                and receipt.data.get(\'exporter_teardown_confirmed\') is True\n                and receipt.data.get(\'guardian_tasks_resolved\') is True\n                and receipt.data.get(\'retained_evidence_bound\') is True, \'cleanup remains unresolved\')\n        return replace(s, phase=Phase.RELEASED, cleanup_required=False)\n    raise Refusal(\'unsupported lifecycle event\')\n\n\ndef watchdog_tick(state, now_ms, policy):\n    """Independent host timer path: it requires no response from the controller."""\n    state.validate(policy)\n    uint(now_ms, \'clock\')\n    if state.phase == Phase.RELEASED:\n        return state\n    if state.phase == Phase.QUARANTINED:\n        # STOPPING is an obligation to revalidate and stop the ORIGINAL identity.\n        # It never authorizes acting on the identity supplied in a bad receipt.\n        return replace(state, phase=Phase.STOPPING, reason=\'quarantined owned cleanup remains due\')\n    if now_ms < state.last_ms:\n        return replace(state, phase=Phase.QUARANTINED, reason=\'monotonic clock rollback\',\n                       requires_ownership_revalidation=True)\n    if state.phase in (Phase.RELEASED, Phase.STOPPED_HELD, Phase.STOPPING):\n        return state\n    if now_ms >= state.deadline_ms:\n        return replace(state, phase=Phase.STOPPING, reason=\'startup deadline\')\n    if now_ms - state.last_ms > policy.sample_ms + policy.maximum_observation_ms:\n        return replace(state, phase=Phase.STOPPING, reason=\'guardian observation missing\')\n    # Do not update last_ms: polling must not refresh an absent observation.\n    return state\n', 'test_lifecycle.py': '"""Deterministic pure fixtures; no Windows, RPC, filesystem or process adapters."""\nimport unittest\nfrom dataclasses import replace\nfrom lifecycle import *\n\nH = \'a\' * 64\nJ = \'b\' * 64\n\n\nclass LifecycleCases(unittest.TestCase):\n    def setUp(self):\n        self.identity = Identity(\'boot-a\', \'attempt-a\', \'vm-a\', H)\n        self.policy = GrowthPolicy(64*MIB, MIB, 1000, 2000, 30000, 15000, H)\n        self.o = Observation(self.identity, 1000, RPC_TOTAL+PENDING+HOST_FLOOR+VARIATION,\n            DISK_FLOOR+BOOT_CAP+ARTIFACT_CAP+64*MIB, 0, 0, 0, True, H, H, H, H, True, J, MIB)\n        self.prerequisites = {key:H for key in (\'guest_dependencies\',\'boot_and_seed\',\n            \'attachment_and_fencing\',\'readiness_verifier\',\'guardian_adapter\',\'disk_growth_qualification\')}\n        self.s = initial_state(self.o,self.identity,1000,self.policy,self.prerequisites,H)\n\n    def receipt(self, issuer, data, sequence=0, at=1001, identity=None):\n        return Receipt(identity or self.identity, sequence, at, True, issuer, data)\n\n    def transition(self, event, issuer, data, state=None, sequence=0, at=1001):\n        return next_state(state or self.s, event, self.receipt(issuer,data,sequence,at),at,self.policy)\n\n    def test_exact_initial_memory_boundary(self):\n        self.assertEqual(len(admit(self.o,self.identity,1000,self.policy,self.prerequisites,H)),64)\n        with self.assertRaisesRegex(Refusal,\'insufficient memory\'):\n            admit(replace(self.o,physical_free_bytes=self.o.physical_free_bytes-1),self.identity,1000,self.policy,self.prerequisites,H)\n\n    def test_disk_margin_is_in_addition_to_artifacts(self):\n        with self.assertRaisesRegex(Refusal,\'insufficient disk\'):\n            admit(replace(self.o,disk_free_bytes=self.o.disk_free_bytes-1),self.identity,1000,self.policy,self.prerequisites,H)\n        with self.assertRaises(Refusal):\n            replace(self.policy,disk_margin_bytes=0).validate()\n        with self.assertRaises(Refusal):\n            replace(self.policy,disk_margin_bytes=MIB).validate()\n\n    def test_required_dependencies_no_boolean_bypass(self):\n        for key in self.prerequisites:\n            missing=dict(self.prerequisites);del missing[key]\n            with self.assertRaises(Refusal):admit(self.o,self.identity,1000,self.policy,missing,H)\n        bad=dict(self.prerequisites);bad[\'guardian_adapter\']=True\n        with self.assertRaises(Refusal):admit(self.o,self.identity,1000,self.policy,bad,H)\n\n    def test_stale_and_unknown_pending_denied(self):\n        for o in (replace(self.o,pending_complete=False),replace(self.o,host_authenticated=False),\n                  replace(self.o,monotonic_ms=1001),replace(self.o,admitted_boot_sha256=J)):\n            with self.assertRaises(Refusal):admit(o,self.identity,1000,self.policy,self.prerequisites,H)\n        with self.assertRaises(Refusal):admit(self.o,self.identity,11001,self.policy,self.prerequisites,H)\n\n    def test_start_requires_live_independent_guardian(self):\n        with self.assertRaises(Refusal):self.transition(\'start\',\'host-controller\',{\'owned_start_worker_bound\':True})\n        with self.assertRaises(Refusal):self.transition(\'arm\',\'host-guardian\',{\'live_instance\':True})\n        s=self.transition(\'arm\',\'host-guardian\',{\'live_instance\':True,\'independent_deadline_live\':True,\n            \'start_fence_armed\':True,\'deadline_ms\':901000})\n        s=self.transition(\'start\',\'host-controller\',{\'owned_start_worker_bound\':True},s,1,1002)\n        self.assertEqual(s.phase,Phase.STARTING)\n\n    def test_exact_deadline_includes_delayed_start(self):\n        s=replace(self.s,phase=Phase.ARMED)\n        s=self.transition(\'start\',\'host-controller\',{\'owned_start_worker_bound\':True},s,0,901000)\n        self.assertEqual(s.phase,Phase.STOPPING)\n        self.assertEqual(s.deadline_ms,901000)\n\n    def test_missing_sample_does_not_reset_clock(self):\n        self.assertEqual(watchdog_tick(self.s,2000,self.policy).last_ms,1000)\n        self.assertEqual(watchdog_tick(self.s,4001,self.policy).phase,Phase.STOPPING)\n        self.assertEqual(watchdog_tick(self.s,999,self.policy).phase,Phase.QUARANTINED)\n\n    def test_wrong_identity_quarantines_without_targeting_replacement(self):\n        r=self.receipt(\'host-guardian\',{},identity=replace(self.identity,vm_guid=\'replacement\'))\n        s=next_state(self.s,\'arm\',r,1001,self.policy)\n        self.assertEqual(s.phase,Phase.QUARANTINED)\n        self.assertEqual(s.identity,self.identity)\n\n    def test_sequence_replay_refused(self):\n        s=replace(self.s,last_sequence=5)\n        with self.assertRaises(Refusal):next_state(s,\'fail\',self.receipt(\'host-controller\',{},5),1001,self.policy)\n\n    def test_running_memory_does_not_double_subtract_owned_guest(self):\n        s=replace(self.s,phase=Phase.STARTING)\n        o=replace(self.o,monotonic_ms=1001,owned_memory_bytes=GUEST,support_charged_bytes=SUPPORT,\n                  physical_free_bytes=PENDING+HOST_FLOOR+VARIATION)\n        okay=self.transition(\'observe\',\'host-guardian\',{\'observation\':o},s)\n        self.assertEqual(okay.phase,Phase.STARTING)\n        bad=self.transition(\'observe\',\'host-guardian\',{\'observation\':replace(o,physical_free_bytes=o.physical_free_bytes-1)},s)\n        self.assertEqual(bad.phase,Phase.STOPPING)\n\n    def test_unexpected_workload_and_boot_changes_stop(self):\n        s=replace(self.s,phase=Phase.STARTING)\n        for field in (\'existing_vm_set_sha256\',\'existing_process_set_sha256\',\'pending_sha256\',\'admitted_boot_sha256\'):\n            o=replace(self.o,monotonic_ms=1001,**{field:J})\n            self.assertEqual(self.transition(\'observe\',\'host-guardian\',{\'observation\':o},s).phase,Phase.STOPPING)\n\n    def test_boot_or_guest_report_is_not_ready(self):\n        s=replace(self.s,phase=Phase.STARTING)\n        with self.assertRaises(Refusal):self.transition(\'ready\',\'guest-stdout\',{},s)\n        with self.assertRaises(Refusal):self.transition(\'ready\',\'qualified-readiness-verifier\',{\'guardian_live\':True},s)\n        s=self.transition(\'ready\',\'qualified-readiness-verifier\',{\'verified_chain_set\':(\'l1-execution\',\'l1-consensus\',\'base-execution\',\'base-rollup\'),\n            \'guardian_live\':True,\'resource_receipt_current\':True,\'attachment_fenced\':True},s)\n        self.assertEqual(s.phase,Phase.READY_TRIAL)\n        self.assertEqual(watchdog_tick(s,901000,self.policy).phase,Phase.STOPPING)\n\n    def test_off_without_late_start_fence_keeps_reservation(self):\n        s=replace(self.s,phase=Phase.STOPPING)\n        with self.assertRaises(Refusal):self.transition(\'off\',\'host-guardian\',{\'vm_state\':\'Off\',\'assigned_memory_bytes\':0},s)\n        s=self.transition(\'off\',\'host-guardian\',{\'vm_state\':\'Off\',\'assigned_memory_bytes\':0,\'start_worker_dead\':True,\'late_start_fenced\':True},s)\n        self.assertEqual(s.phase,Phase.STOPPED_HELD)\n        with self.assertRaises(Refusal):self.transition(\'release\',\'host-controller\',{\'guest_write_fence_confirmed\':True},s,1,1002)\n\n    def test_cleanup_proven_before_release_and_no_replay(self):\n        s=replace(self.s,phase=Phase.STOPPED_HELD)\n        s=self.transition(\'release\',\'host-controller\',{\'guest_write_fence_confirmed\':True,\'exporter_teardown_confirmed\':True,\n            \'guardian_tasks_resolved\':True,\'retained_evidence_bound\':True},s)\n        self.assertEqual(s.phase,Phase.RELEASED)\n        with self.assertRaises(Refusal):self.transition(\'start\',\'host-controller\',{\'owned_start_worker_bound\':True},s,1,1002)\n\n    def test_origin_and_deadline_are_bound_at_admission_and_resume(self):\n        self.assertEqual(self.s.deadline_ms-self.s.origin_ms,STARTUP_MS)\n        for s in (replace(self.s,deadline_ms=1801000),replace(self.s,origin_ms=True),\n                  replace(self.s,last_ms=-1),replace(self.s,deadline_ms=901000.0)):\n            with self.assertRaises(Refusal):watchdog_tick(s,1001,self.policy)\n        for clock in (True,-1,float(\'nan\'),1000.0):\n            with self.assertRaises(Refusal):initial_state(self.o,self.identity,clock,self.policy,self.prerequisites,H)\n        with self.assertRaises(Refusal):initial_state(replace(self.o,pending_complete=False),self.identity,1000,self.policy,self.prerequisites,H)\n\n    def test_quarantine_keeps_original_deadline_and_cleanup_obligation(self):\n        running=replace(self.s,phase=Phase.STARTING)\n        bad=self.receipt(\'host-guardian\',{},identity=replace(self.identity,vm_guid=\'replacement\'))\n        quarantined=next_state(running,\'observe\',bad,1001,self.policy)\n        self.assertTrue(quarantined.cleanup_required)\n        stopped=watchdog_tick(quarantined,901000,self.policy)\n        self.assertEqual(stopped.phase,Phase.STOPPING)\n        self.assertEqual(stopped.identity,self.identity)\n        self.assertEqual(stopped.deadline_ms,901000)\n        with self.assertRaises(Refusal):self.transition(\'off\',\'host-guardian\',{\'vm_state\':\'Off\',\'assigned_memory_bytes\':0,\n            \'start_worker_dead\':True,\'late_start_fenced\':True},quarantined,0,1002)\n        off=self.transition(\'off\',\'host-guardian\',{\'vm_state\':\'Off\',\'assigned_memory_bytes\':0,\n            \'start_worker_dead\':True,\'late_start_fenced\':True,\'original_ownership_revalidated\':True},quarantined,0,1002)\n        self.assertEqual(off.phase,Phase.STOPPED_HELD)\n        self.assertTrue(off.cleanup_required)\n\n    def test_clock_rollback_cannot_erase_cleanup(self):\n        running=replace(self.s,phase=Phase.STARTING,last_ms=2000)\n        quarantined=watchdog_tick(running,1999,self.policy)\n        self.assertEqual(quarantined.phase,Phase.QUARANTINED)\n        self.assertTrue(quarantined.cleanup_required)\n        self.assertEqual(watchdog_tick(quarantined,901000,self.policy).phase,Phase.STOPPING)\n\n    def test_admitted_policy_cannot_be_replaced(self):\n        different=replace(self.policy,disk_margin_bytes=65*MIB)\n        different.validate()  # Individually valid is not the admitted policy.\n        with self.assertRaisesRegex(Refusal,\'admitted policy changed\'):\n            watchdog_tick(self.s,1001,different)\n        with self.assertRaisesRegex(Refusal,\'admitted policy changed\'):\n            next_state(self.s,\'fail\',self.receipt(\'host-controller\',{}),1001,different)\n\n    def test_guest_boot_writes_keep_identity_without_live_content_hash(self):\n        running=replace(self.s,phase=Phase.STARTING)\n        changed=replace(self.o,monotonic_ms=1001,runtime_boot_allocated_bytes=2*MIB)\n        # Mutable contents are deliberately absent from Observation. Same protected\n        # file identity and admitted artifact digest survive normal filesystem writes.\n        self.assertEqual(self.transition(\'observe\',\'host-guardian\',{\'observation\':changed},running).phase,Phase.STARTING)\n        replaced=replace(changed,runtime_boot_identity_sha256=H)\n        self.assertEqual(self.transition(\'observe\',\'host-guardian\',{\'observation\':replaced},running).phase,Phase.STOPPING)\n        oversized=replace(changed,runtime_boot_allocated_bytes=BOOT_CAP+1)\n        self.assertEqual(self.transition(\'observe\',\'host-guardian\',{\'observation\':oversized},running).phase,Phase.STOPPING)\n\n    def test_quarantine_revalidation_latch_survives_watchdog_and_resume(self):\n        running=replace(self.s,phase=Phase.STARTING)\n        bad=self.receipt(\'host-guardian\',{},identity=replace(self.identity,vm_guid=\'replacement\'))\n        quarantine=next_state(running,\'observe\',bad,1001,self.policy)\n        stopping=watchdog_tick(quarantine,1002,self.policy)\n        resumed=State(**stopping.__dict__)\n        self.assertTrue(resumed.requires_ownership_revalidation)\n        off={\'vm_state\':\'Off\',\'assigned_memory_bytes\':0,\'start_worker_dead\':True,\'late_start_fenced\':True}\n        with self.assertRaisesRegex(Refusal,\'revalidation remains required\'):\n            self.transition(\'off\',\'host-guardian\',off,resumed,0,1003)\n        held=self.transition(\'off\',\'host-guardian\',dict(off,original_ownership_revalidated=True),resumed,0,1003)\n        self.assertEqual(held.phase,Phase.STOPPED_HELD)\n        self.assertFalse(held.requires_ownership_revalidation)\n        self.assertTrue(held.cleanup_required)\n\n    def test_released_stale_timer_is_inert(self):\n        held=replace(self.s,phase=Phase.STOPPED_HELD)\n        released=self.transition(\'release\',\'host-controller\',{\'guest_write_fence_confirmed\':True,\n            \'exporter_teardown_confirmed\':True,\'guardian_tasks_resolved\':True,\'retained_evidence_bound\':True},held)\n        stale=watchdog_tick(released,999,self.policy)\n        self.assertEqual(stale,released)\n        self.assertEqual(watchdog_tick(stale,901001,self.policy),released)\n\n\nif __name__ == \'__main__\':\n    unittest.main()\n'}
