growth=0
for name,cap in CONFIG['serviceCapsMiB'].items():
 q=Path('/sys/fs/cgroup/system.slice')/name;assert(q/'memory.max').read_text().strip()==str(cap<<20);growth+=max(0,(cap<<20)-int((q/'memory.current').read_text()))
assert mem-growth-(256<<20)>=1536<<20
