print(json.dumps({'tests':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'skipped':len(result.skipped),'passed':result.wasSuccessful(),'output':stream.getvalue(),'uid':os.geteuid(),'resourceResidualBytes':mem-growth-(256<<20),'nativeExecuted':False}))
